def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_requirements = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_requirements.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0.0))

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return min(budget, 95.0)
        return min(budget, 20.0)

    total_agents = 1 + len(alive_opponents)
    total_req = WATER_REQ
    for req in opp_requirements:
        total_req += req

    scarcity = 0.0
    if total_req > 0:
        scarcity = max(0.0, (total_req - supply) / float(total_req))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 0.0

    urgent = (hp <= 2) or (no_water_days >= 1)
    very_urgent = (hp <= 1) or (no_water_days >= 2)
    tight_supply = supply <= 18
    loose_supply = supply >= 23

    if very_urgent:
        target = max(118.0, highest_prev + 4.0)
    elif urgent:
        if tight_supply:
            target = max(108.0, highest_prev + 2.0)
        else:
            target = max(96.0, avg_prev + 1.5)
    else:
        if loose_supply:
            target = 18.0
        elif scarcity < 0.35:
            target = 28.0
        elif scarcity < 0.5:
            target = 42.0
        else:
            target = 58.0

        if highest_prev >= 110.0 and hp >= 4 and no_water_days == 0:
            target = min(target, 26.0)
        elif highest_prev >= 90.0 and hp >= 5 and no_water_days == 0:
            target = min(target, 34.0)

    remaining_days = max(0, 10 - int(day) + 1)
    reserve = remaining_days * 18.0
    max_affordable = budget
    if not urgent:
        max_affordable = max(0.0, budget - reserve)
        max_affordable = min(budget, max(22.0, max_affordable))

    bid = min(target, max_affordable)

    if urgent and bid < 85.0:
        bid = min(budget, 85.0)
    if very_urgent and bid < 110.0:
        bid = min(budget, 110.0)

    if budget < 25.0:
        bid = budget

    if bid < 0.0:
        bid = 0.0
    return float(min(budget, bid))

