def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Determine aggressiveness target
    # Supply fraction: higher supply means we can afford lower bids to win; lower supply requires stronger bids.
    supply_mid = (MIN_SUPPLY + MAX_SUPPLY) / 2.0
    supply_factor = 0.55 if supply >= supply_mid else 0.85

    # Pressure from others: if someone bid very high yesterday, others likely compete; avoid chasing too hard.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.7:
        pressure = 0.25
    elif highest_prev_bid >= DAILY_SALARY * 0.35:
        pressure = 0.15
    else:
        pressure = 0.05

    # If I'm in danger, bid more; if I'm safe, bid less to conserve.
    if hp <= 2 or no_water_days >= 1:
        danger = 0.35
    elif hp <= 5:
        danger = 0.18
    else:
        danger = 0.08

    # Baseline bid: moderate share of daily salary.
    target = DAILY_SALARY * (0.40 * supply_factor + pressure + danger)

    # Convert target to a bid that is unlikely to be wasteful.
    # If supply is near minimum, slightly increase; if near maximum, slightly decrease.
    if supply <= MIN_SUPPLY + 1.0:
        target *= 1.10
    elif supply >= MAX_SUPPLY - 1.0:
        target *= 0.90

    # Cap target relative to others' max yesterday bid: don't overpay massively.
    if highest_prev_bid > 0.0:
        target = min(target, highest_prev_bid * 0.65 + 0.5 * DAILY_SALARY * 0.25)

    # Ensure we can afford it.
    bid = float(min(budget, target))

    # If budget is extremely low, still bid something proportional.
    min_bid = 0.0
    if budget > 0.0:
        min_bid = float(min(budget, DAILY_SALARY * 0.08))

    if bid < min_bid:
        bid = min_bid

    # Final sanity: bids should be non-negative.
    if bid < 0.0:
        bid = 0.0

    return bid
